var(--muted);font-size:var(--fs-sm)}.incident-table{width:100%;border-collapse:collapse;table-layout:fixed}.incident-table thead{background:var(--soft);color:var(--muted)}.incident-table th{text-align:left;font-size:var(--fs-xs);font-weight:500;text-transform:uppercase;letter-spacing:.06em;padding:var(--space-3)}.incident-table td{padding:var(--space-4) var(--space-3);border-bottom:1px solid var(--line);vertical-align:middle;font-size:var(--fs-sm)}.incident-table th:first-child{width:66px}.incident-table th:nth-child(3){width:132px}.incident-table th:nth-child(4){width:116px}.incident-table th:nth-child(5){width:94px}.incident-title{border:0;padding:0;background:transparent;text-align:left;font-weight:500;font-size:var(--fs-base);line-height:1.25}.incident-title:hover{text-decoration:underline}.incident-meta{display:flex;flex-wrap:wrap;gap:0 var(--space-3);color:var(--muted);font-size:var(--fs-xs);margin-top:var(--space-2)}.sev{font-family:PlexMono,monospace;font-size:var(--fs-xs);font-weight:400;display:inline-block;border:1px solid var(--line);padding:var(--space-1) var(--space-2);border-radius:var(--radius-sm);white-space:nowrap}.sev-1{color:var(--danger);background:var(--danger-bg);border-color:var(--danger)}.sev-2{color:var(--warn);background:var(--warn-bg);border-color:var(--warn)}.critical-row{background:var(--danger-bg);box-shadow:inset 3px 0 var(--danger)}.unassigned{color:var(--danger);font-weight:500}.status{display:flex;align-items:center;gap:var(--space-2)}.table-note{display:flex;align-items:center;justify-content:space-between;font-size:var(--fs-sm);color:var(--muted);padding:var(--space-4) 0;gap:var(--space-3)}.pager{display:flex;gap:var(--space-2)}.pager .btn{min-height:40px;padding:var(--space-2) var(--space-3)}.side-section{padding-bottom:var(--space-6);margin-bottom:var(--space-6);border-bottom:1px solid var(--line)}.side-section h2{margin-bottom:var(--space-4)}.oncall-item{margin-bottom:var(--space-4)}.oncall-item .eyebrow{color:var(--muted);margin-bottom:var(--space-1)}.owner-gap{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);padding-top:var(--space-4);font-size:var(--fs-sm)}.owner-gap strong{color:var(--danger)}.service-row{margin-bottom:var(--space-4)}.service-label{display:flex;justify-content:space-between;font-size:var(--fs-sm);margin-bottom:var(--space-2);gap:var(--space-2)}.bar-track{height:5px;background:var(--line)}.bar-fill{height:100%;width:var(--bar);background:var(--chart)}.resolved-item{padding:var(--space-3) 0;border-bottom:1px solid var(--line)}.resolved-item:last-child{border:0}.resolved-item p{font-size:var(--fs-sm);margin:var(--space-1) 0}.resolved-item .small{font-size:var(--fs-xs)}.board-foot{display:flex;justify-content:space-between;gap:var(--space-4);margin-top:var(--space-6);padding-top:var(--space-4);border-top:1px solid var(--line);font-size:var(--fs-xs);color:var(--muted)}
