px;border:1px solid var(--muted);border-radius:var(--radius-md);padding:var(--space-3);background:var(--surface);color:var(--fg)}textarea{min-height:90px;resize:vertical}input[aria-invalid=true]{border:2px solid var(--danger)}.field .hint{font-size:var(--fs-sm);color:var(--muted);margin-top:var(--space-2)}.field .error{margin-top:var(--space-2)}.stack-actions{display:grid;gap:var(--space-2);margin-top:var(--space-5)}.transfer{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:var(--space-4) 0;margin:var(--space-5) 0;display:grid;grid-template-columns:1fr auto 1fr;gap:var(--space-3);align-items:center}.transfer .small{font-size:var(--fs-xs)}.status-mark{width:48px;height:48px;border-radius:var(--radius-round);background:var(--success-bg);color:var(--success);display:grid;place-items:center;font-size:var(--fs-xl);margin:var(--space-2) 0 var(--space-5)}
